from lib import *
S = SS('t19')
steps = [
    step("六种库存扣减方式,同样的 3000 个买家用 32 个线程抢 1000 件。先 SELECT 再 UPDATE(不加锁):3000 个请求全部“成功”,超卖 2000 件,而 MySQL 里最终库存是 901(并发的写互相覆盖,账都对不上)。SELECT ... FOR UPDATE、一条条件 UPDATE(WHERE qty >= 1)、乐观锁 version CAS、库存拆成 8 行、Redis Lua 先扣减:成功数都是 1000,超卖 0,MySQL 最终库存 0;Redis 方案异步落库的订单行数也是 1000。检查和扣减必须在同一个原子操作里。", t=tl(S(1)), mark=lidx(S(1), '先 SELECT 再 UPDATE(不加锁)'), done=lidx(S(1), 'SELECT ... FOR UPDATE', '一条条件 UPDATE', 'Redis Lua'), b=bars([['不加锁:成功的单数', 3000, '3000(库存只有 1000)'], ['不加锁:超卖', 2000, '2000'], ['其余五种:超卖', 0, '0']], 3000, mark=[0, 1], done=[2]), kv=KV([['不加锁', '3000 个都成功,超卖 2000'], ['其余五种', '成功正好 1000,超卖 0'], ['要点', '检查与扣减放进同一个原子操作']], ['要点'])),
    step("吞吐与延迟(3 轮取中位数,库存只有 1000、卖完后大部分请求是失败请求)。不加锁 11338 请求/秒(但结果是错的);SELECT ... FOR UPDATE 9493;一条条件 UPDATE 11135,p99 12.8 ms;乐观锁只有 1121,p99 168.7 ms(32 个线程抢同一行,大量重试);拆成 8 行 3434;Redis Lua 先扣减 17262,p99 7.0 ms,3000 个请求 0.19 s 处理完,全部落到 MySQL 用了 0.24 s,最后一个订单比用户看到成功晚 0.04 s 才进库。单行条件 UPDATE 是最简单又够快的正确做法。", t=tl(S(2)), mark=lidx(S(2), '乐观锁(version CAS'), done=lidx(S(2), '一条条件 UPDATE', 'Redis Lua 先扣减'), b=bars([['条件 UPDATE 请求/秒', 11135, '11135'], ['FOR UPDATE 请求/秒', 9493, '9493'], ['乐观锁 请求/秒', 1121, '1121'], ['Redis Lua 请求/秒', 17262, '17262']], 17500, done=[0, 1, 3], mark=[2]), kv=KV([['条件 UPDATE', '11135 请求/秒,正确又简单'], ['乐观锁', '1121 请求/秒,p99 168.7 ms'], ['Redis Lua', '17262 请求/秒,异步落库晚 0.04 s']], ['条件 UPDATE'])),
    step("同样的 3000 个买家,但库存很大(10 万件,没有人会被拒绝),去掉“卖完之后的失败请求”的影响,只看热点行的争用。FOR UPDATE 5818 请求/秒;一条条件 UPDATE 7741;拆成 8 行 9021(单行争用小了,库存充足时更快);Redis Lua 17792。乐观锁只有 528 请求/秒,而且成功数只有 2323 到 2349(应为 3000)——32 个线程抢同一行时,有的买家重试 50 次仍然抢不到,库存明明充足却被拒绝。上一节里拆成 8 行更慢,是因为卖完之后每个失败请求要把 8 个分片挨个试一遍。", t=tl(S(3)), mark=lidx(S(3), '乐观锁(version CAS'), done=lidx(S(3), '库存拆成 8 行', 'Redis Lua'), b=bars([['条件 UPDATE 请求/秒', 7741, '7741'], ['拆 8 行 请求/秒', 9021, '9021'], ['乐观锁 请求/秒', 528, '528'], ['乐观锁成功的单数(应为 3000)', 2323, '2323 ~ 2349']], 9100, done=[0, 1], mark=[2, 3]), kv=KV([['拆 8 行', '库存充足时 9021,比单行快'], ['乐观锁', '重试 50 次仍抢不到,成功 2323 ~ 2349'], ['卖完之后', '分片的失败请求要试 8 行']], ['乐观锁'])),
    step("Redis 先扣减的代价:Redis 没开持久化,被 kill -9 后只能用 MySQL 里的库存重新初始化,而异步落库还没追上。落库每批间隔 300 ms,Redis 在确认第 600 个订单时被杀:此刻已经对用户确认成功的订单 600 个,落到 MySQL 的只有 2 个(落后 598 个);重启后按 MySQL 里的库存 898 重新初始化 Redis,而此时 MySQL 库存本该是 400。之后的买家继续抢,最终对用户确认成功的订单一共 1526 个,库存只有 1000 件,超卖 526 件,MySQL 里的库存最终是 -526。用 Redis 扛住瞬时流量没问题,但它的计数一旦丢了,就要靠持久化或可靠的重建办法,否则丢的是还没落库的那一段。", t=tl(S(4)), mark=lidx(S(4), 'Redis 被杀时', '超卖 526 件'), done=lidx(S(4), '重启后按 MySQL'), b=bars([['被杀时已确认的订单', 600, '600'], ['其中已落库', 2, '2'], ['最终确认的订单(库存 1000)', 1526, '1526'], ['超卖', 526, '526']], 1600, cur=[0, 1], mark=[2, 3]), kv=KV([['Redis 被杀', '没持久化,计数丢失'], ['用 MySQL 重建', '落库落后 598 个,被重复卖出'], ['结果', '1526 个订单,库存 1000,超卖 526']], ['结果'])),
]
A = mkartt('t19', 19, '分布式事务,库存扣减,超卖,Redis,MySQL,乐观锁,真实验证,动画演示',
    '实测六种库存扣减方式抢 1000 件:先读后写 3000 个都成功超卖 2000;FOR UPDATE、条件 UPDATE、乐观锁、分片、Redis Lua 都是 0 超卖;乐观锁因争用只有 1121 请求/秒、库存充足时成功数也只有 2323 到 2349(应为 3000);Redis 没持久化被 kill -9 后按 MySQL 重建,超卖 526 件。',
    '秒杀和下单最怕超卖。几种常见的库存扣减方式——读后写、加锁、条件 UPDATE、乐观锁、库存分片、Redis 预扣——到底哪些防得住?各自多快?Redis 预扣的代价是什么?这篇用真实的 MySQL 和 Redis,用同样的 3000 个买家抢 1000 件,把它们摆在一起量。',
    [('2000', '先 SELECT 再 UPDATE 时 3000 个买家抢 1000 件的超卖数(其余五种都是 0)'), ('11135 vs 1121', '单行条件 UPDATE 与乐观锁的吞吐(请求/秒,32 线程抢同一行)'), ('526', 'Redis 预扣、没持久化被 kill -9 并按 MySQL 重建后,超卖的件数')],
    [('检查与扣减要原子', '<p>先读后写会超卖;把检查写进同一条 UPDATE 的 WHERE,或加行锁,都能防住。</p>'),
     ('吞吐', '<p>单行条件 UPDATE 既简单又够快;乐观锁在热点行上大量重试;分片在库存充足时更快;Redis 预扣最快。</p>'),
     ('争用与分片', '<p>乐观锁在 32 线程抢同一行时,有买家重试 50 次仍失败;分片把争用分散,但卖完后失败请求要试多个分片。</p>'),
     ('Redis 预扣的代价', '<p>异步落库有延迟窗口,Redis 一旦丢数据而用 MySQL 重建,落后的这段会被重复卖出。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例(stock 表,默认 REPEATABLE-READ)和自己起的 Redis 8.10.2,32 个线程、3000 个买家各买 1 件;乐观锁最多重试 50 次;分片是 8 行、随机选一行再依次试;Redis 方案是 Lua 脚本检查并 DECR,成功的订单由另一个线程每批最多 500 个异步写进 MySQL;第三节把落库节奏放慢到每批 100 个、间隔 300 ms 以暴露窗口',
     '没有验证:Redis 开了 AOF / RDB 持久化后窗口有多大;Redis 主从切换下的丢失;库存预扣后订单取消的回补(第 6 到 9 篇的 TCC / Saga 范围);更大并发(几千线程)与真实网络;MySQL 的 SELECT ... FOR UPDATE 在不同隔离级别下的差别;热点行的 innodb 参数调优'],
    '库存扣减')
